[70750] = {id=70750,name="Aiding the Accord",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2112,description="You there! Yes, I'm speaking to you. Who else do you see around here? Therazal glances quickly at quite a few passers by.> Ignore them. They are not part of this request. It is you I've heard of, and you I wish to speak with! The Valdrakken Accord has asked me to seek out those who have shown they are making a name for themselves across the Isles, and those who seek to ensure our allies and their safety remain the highest priority. Do what you do best, friend. You shall be rewarded handsomely.",objectivesText="Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: The tales of your exploits ring true, but what is it you bring me? Information, news? Get on with it.",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},ends={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="Aiding the Accord"},
