[72068] = {id=72068,name="Aiding the Accord: A Feast For All",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2112,description="Our allies require your aid, ! Your efforts throughout the Isles have not gone unnoticed. Our trusted allies to the south, the Iskaara Tuskarr , seek to celebrate your accomplishments with a feast of all feasts! Journey to the lands of Iskaara whilst continuing your work alongside the allies of the Accord. When you reach the shimmering waters of the southern lands do not hesitate to participate in the celebrations!",objectivesText="Travel to Iskaara in The Azure Span and participate in a Community Feast. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Back so soon? Where does the time go?",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},ends={{npcID=196499,x=0.502,y=0.56,zoneID=13862}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="Aiding the Accord: A Feast For All"},
