[72373] = {id=72373,name="Aiding the Accord: The Hunt is On",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause. Whilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts. There is much to be done. Best not delay.",objectivesText="Assist the Maruuk on a Hunt within the Dragon Isles. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Has our renowned traveler returned with more news of success?",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862}},ends={{npcID=196499,x=0.502,y=0.56,zoneID=13862}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="Aiding the Accord: The Hunt is On"},
[72374] = {id=72374,name="Aiding the Accord: Dragonbane Keep",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2025,description="Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. A lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances. We await your return, .",objectivesText="Travel to The Waking Shores and lay siege to Dragonbane Keep. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?",starts={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},ends={{npcID=196499,x=0.502,y=0.56,zoneID=13862},{npcID=199336,x=0.764,y=0.342,zoneID=13644}},coords={x=0.502,y=0.56,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="Aiding the Accord: Dragonbane Keep"},
[72375] = {id=72375,name="Aiding the Accord: The Isles Call",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13644,mapID=2112,description="Your actions have not gone unnoticed. Across the Isles, our allies seek to ensure the safety of all who venture throughout these lands. There are, however, some who would seek to end your... work, as it impedes in their plans. Do what you must to ensure our allies are protected.",starts={{npcID=196499,x=0.502,y=0.56,mapID=2112},{npcID=199336,x=0.764,y=0.342,mapID=2022}},ends={{npcID=196499,x=0.502,y=0.56,mapID=2112},{npcID=199336,x=0.764,y=0.342,mapID=2022}},coords={x=0.502,y=0.56,source="quest_giver",mapID=2022},questType="world",worldTaskTitle="Aiding the Accord: The Isles Call"},
[72783] = {id=72783,name="Crafting Orders",level=40,requiredLevel=40,faction="both",expansion=9,zoneID=13862,mapID=2112,description="That's a nifty thing you got there from the titan device. Now hand it over! Just kiddin'! I wouldn't know the first thing about how to use that. Do you? Go talk to Mimzy Sprazzlerock. She's got a whole gig setup findin' folks to do something called \"crafting orders\". You put up the goods, someone takes 'em and crafts something for you. Simple, right? Go talk to Mimzy to check it out! And don't tell her I sent you.",objectivesText="Speak with Head Clerk Mimzy Sprazzlerock to learn about Crafting Orders.",starts={{npcID=196066,x=0.84,y=0.542,zoneID=13862}},ends={{npcID=196475,x=0.838,y=0.536,zoneID=13862}},coords={x=0.84,y=0.542,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="Crafting Orders"},
[72952] = {id=72952,name="The Scary Vault of Ur",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Tacha's big ears heard some noise in one of the tunnels. We took a peek inside. I'm not going to lie: it's grim in there. Pretty terrifying. All sorts of horrible creatures. Not the sort of thing Tacha and I usually deal with up close. You have experience dealing with monsters, right? Excellent. You go first. Don't worry. Once it's safe, we'll come in and join you. Really, it's the least we can do.",starts={{npcID=200040,x=0.29,y=0.53,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151}},coords={x=0.29,y=0.53,source="quest_giver",mapID=2151},questType="world",worldTaskTitle="The Scary Vault of Ur"},
[72953] = {id=72953,name="Zskera Vault: Az",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="We have discovered a series of vaults below the island. Neltharion hoarded treasures, accumulated knickknacks, and stashed away the results of his failed experiments. When I say he's a hoarder, I'm not kidding! He filled chamber after chamber, and in time, they were all forgotten... until now. Treasure awaits us behind these locked doors! Also, the occasional deathtrap. Also, treasure! Now we have the keys to unlock those doors.",starts={{npcID=200040,x=0.29,y=0.53,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151},{npcID=202218,x=0.29,y=0.57,mapID=2151}},coords={x=0.29,y=0.53,source="quest_giver",mapID=2151},questType="world",worldTaskTitle="Zskera Vault: Az"},
[72954] = {id=72954,name="Zskera Vault: Ix",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="Wulferd spotted some pirates making their way into the vaults this morning. If we don't act fast, they'll strip the vault clean! We're going into the vault immediately. There's no time to lose. Will you be joining us?",starts={{npcID=200040,x=0.29,y=0.53,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151}},coords={x=0.29,y=0.53,source="quest_giver",mapID=2151},questType="world",worldTaskTitle="Zskera Vault: Ix"},
[72955] = {id=72955,name="Zskera Vault: Kx",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14433,mapID=2151,description="I was afraid this might happen. The Sundered Flame is here. And they've discovered the Vaults. Of course, we have to stop them. Anything useful or dangerous, they're going to take straight to Sarkareth. I've had enough of his nonsense. Time for you to do what you do best.",starts={{npcID=200040,x=0.29,y=0.53,mapID=2151}},ends={{npcID=200040,x=0.29,y=0.53,mapID=2151}},coords={x=0.29,y=0.53,source="quest_giver",mapID=2151},questType="world",worldTaskTitle="Zskera Vault: Kx"},
