[75259] = {id=75259,name="Aiding the Accord: Zskera Vaults",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,mapID=2025,description="Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Pathfinders of the Dragonscale Expedition are delving deeper into the Zskera Vaults on the Forbidden Reach. They are asking for brave adventurers to help them explore these new mysteries. We await your return, .",starts={{npcID=196499,x=0.502,y=0.56,mapID=2112}},ends={{npcID=196499,x=0.502,y=0.56,mapID=2112}},coords={x=0.502,y=0.56,source="quest_giver",mapID=2112},questType="world",worldTaskTitle="Aiding the Accord: Zskera Vaults"},
