[75640] = {id=75640,name="Honor the Flame",level=1,requiredLevel=1,faction="both",expansion=9,zoneID=13646,mapID=2024,description="The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, ?",starts={{npcID=204414,x=0.122,y=0.476,mapID=2024}},ends={{npcID=401141,x=0.122,y=0.476,mapID=2024}},coords={x=0.122,y=0.476,source="quest_giver",mapID=2024},questType="world",worldTaskTitle="Honor the Flame"},
