[75665] = {id=75665,name="A Worthy Ally: Loamm Niffen",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14022,mapID=2133,description="Djaradin, dracthyr, and dragons! Oh my! You can't help but smell the danger in these here caverns. We sure could use some armed assistance. You scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele. How about it? Get out there and bury the competition?",objectivesText="Aid the niffen and their allies throughout Zaralek Cavern . Progress: Are our enemies six feet under?",starts={{mapID=2133,npcID=204254,x=0.565,y=0.556}},ends={{mapID=2133,npcID=204254,x=0.565,y=0.556}},coords={mapID=2133,source="quest_giver",x=0.565,y=0.556},questType="world",worldTaskTitle="A Worthy Ally: Loamm Niffen"},
