[75859] = {id=75859,name="Aiding the Accord: Sniffenseeking",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2025,description="Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Our niffen allies in Zaralek Cavern are always on the lookout for something new and exciting--or smelly. Join them on a dig through the many lost and forgotten caverns in their domain, and see what you find. We await your return, <name>.",objectivesText="Travel to Zaralek Cavern and accompany Myrrit in Loamm on a dig underground. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?",starts={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Sniffenseeking"},
[75860] = {id=75860,name="Aiding the Accord: Researchers Under Fire",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future. Now then, to business. Researchers of the Dragonscale Expedition are exploring the depths of Zaralek Cavern. They are asking for brave adventurers to help protect them from the many dangers in that area. We await your return, <name>.",objectivesText="Travel to Zaralek Cavern and protect the Researchers Under Fire. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.",starts={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Researchers Under Fire"},
[75861] = {id=75861,name="Aiding the Accord: Suffusion Camp",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13644,mapID=2112,description="Ash blows from the south. A dark bargain has been made, <name>, between the djaradin of the Zaqali and Fyrakk. Their forces are building... something. We do not know what their goals are, but they have had no hesitation in displacing anyone and everything in their path. Please, <name>, we need champions like you to undermine these villains and deprive them of their resources. We await your return, <name>.",objectivesText="Travel to a Suffusion Camp and loot a Secured Shipment. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.",starts={{mapID=2112,npcID=196499,x=0.503,y=0.5605},{mapID=2022,npcID=199336,x=0.765,y=0.342}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Suffusion Camp"},
[76361] = {id=76361,name="Fashion Week",faction="both",expansion=9,zoneID=14771,mapID=2112,description="Ah, the Trial of Style is upon us, <class>. The outfits, the creativity, the elegance of the Trial are truly a sight to see. Speak to a Trial of Style Envoy to learn more about the event. A word of warning, those envoys can be... challenging to deal with.",objectivesText="Speak to a Trial of Style Envoy.",starts={{mapID=2112,npcID=199261,x=0.390667,y=0.61},{mapID=2339,npcID=220307,x=0.46,y=0.546},{mapID=2339,npcID=220870,x=0.41,y=0.594}},ends={{mapID=84,npcID=206252,x=0.51,y=0.725},{mapID=85,npcID=206383,x=0.488,y=0.765},{mapID=2339,npcID=236405,x=0.455,y=0.527},{mapID=2393,npcID=258350,x=0.522,y=0.585}},coords={mapID=2112,source="quest_giver",x=0.390667,y=0.61},questType="world",worldTaskTitle="Fashion Week"},
