[77209] = {id=77209,name="Seed Legacy",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14529,mapID=2200,description="For years I worked with Denalan in Teldrassil. His research will be the foundation of how we will restore these seeds. The first step: we must coax them back to life, allowing them to grow into vibrant blossoming plants. I have located suitable patches of soil where the plants can take root and grow, revealing their true potential. We will plant one small, one plump, and one gigantic seed to observe how the quality of the seed can sprout different growth.",objectivesText="Plant a seed at each of the Dreamsoil patches. Progress: Have you planted the seeds?",starts={{mapID=2200,npcID=211265,x=0.596,y=0.168}},ends={{mapID=2200,npcID=211265,x=0.596,y=0.168}},coords={mapID=2200,source="quest_giver",x=0.596,y=0.168},questType="world",worldTaskTitle="Seed Legacy"},
[77251] = {id=77251,name="Shaping the Dreamsurge",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13647,mapID=2024,description="The Emerald Dream is thrumming with energies not felt in ages. Some of that energy is even slipping through the barrier between the dream and Azeroth, coalescing into a glimmering, pollen-like powder. Gather as much as you can. This is not like any event we have seen before!",objectivesText="Gather Dreamsurge Coalescence from around the Dreamsurge. Progress: The winds sparkle with motes of dreaming essence, spreading it over the land.",starts={{mapID=2022,npcID=208649,x=0.584,y=0.678}},ends={{mapID=2022,npcID=208649,x=0.584,y=0.678}},coords={mapID=2022,source="quest_giver",x=0.584,y=0.678},questType="world",worldTaskTitle="Shaping the Dreamsurge"},
[77254] = {id=77254,name="Aiding the Accord: Time Rift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13644,mapID=2112,description="The Bronze Dragonflight have long labored in secret, dealing with temporal anomalies nearly as quickly as they're able to manifest. It would appear, however, that the anomalies have gotten a bit too big as of late. That's where you come in. You can find Soridormi leading an effort against a particularly nasty set of Time Rifts just to the east of Valdrakken . Aid her in whatever way she deems necessary.",objectivesText="Travel to the Tyrhold Reservoir and assist Soridormi in dispelling a Time Rift. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: Do you bring news of your success?",starts={{mapID=2112,npcID=196499,x=0.503,y=0.5605},{mapID=2022,npcID=199336,x=0.765,y=0.342}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Time Rift"},
