[77976] = {id=77976,name="Aiding the Accord: Dreamsurge",level=60,requiredLevel=60,faction="both",expansion=9,zoneID=13862,mapID=2112,description="A group of druids from across Azeroth have gathered to investigate a sudden surge in energies coming from the Emerald Dream. This has the potential to affect us all, . Please aid them in their endeavor to understand this new phenomena.",starts={{npcID=196499,x=0.502,y=0.56,mapID=2112}},ends={{npcID=196499,x=0.502,y=0.56,mapID=2112}},coords={x=0.502,y=0.56,source="quest_giver",mapID=2112},questType="world",worldTaskTitle="Aiding the Accord: Dreamsurge"},
