[78170] = {id=78170,name="Nurturing Ageless Seeds",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=14529,mapID=2200,description="The growth of these seeds is a delicate balance, requiring constant nurturing. I've found that Ageless Dewdrops , gathered from around this area, hold a special energy that can awaken the dormant potential within these seeds. If you could collect some dewdrops and apply them to the plants, we can unlock their full potential.",objectivesText="Nurture each of the seed we planted with Ageless Dewdrops . Progress: Have you given the Ageless Dewdrops to the blossoming seeds?",starts={{mapID=2200,npcID=211265,x=0.596,y=0.168}},ends={{mapID=2200,npcID=211265,x=0.596,y=0.168}},coords={mapID=2200,source="quest_giver",x=0.596,y=0.168},questType="world",worldTaskTitle="Nurturing Ageless Seeds"},
