[78444] = {id=78444,name="A Worthy Ally: Dream Wardens",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14529,mapID=2200,description="So much change to that which should be unchanging... Rarely has the Dream seen such turmoil. It is meant to be a place of peace. Of life. Champion, we need all the help we can get. I bid you go forth and bring aid to the expanse of the Dream. I have no doubt the Dream will share its plenty with you in return.",objectivesText="Aid the Dream Wardens and their allies throughout the Emerald Dream . Progress: Do take some time to stop and smell all that blooms throughout the Dream. It will enrich your life.",starts={{mapID=2200,npcID=208143,x=0.502,y=0.616}},ends={{mapID=2200,npcID=208143,x=0.502,y=0.616}},coords={mapID=2200,source="quest_giver",x=0.502,y=0.616},questType="world",worldTaskTitle="A Worthy Ally: Dream Wardens"},
[78446] = {id=78446,name="Aiding the Accord: Superbloom",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="As life blooms within the Emerald Dream, the budding World Tree Amirdrassil blooms with it. The Ancient Sprucecrown's ritual empowers mighty life energies all around the tree, encouraging its growth. The more hands there to help protect and nourish Amirdrassil, the better its bloom will be! Please lend your aid to Sprucecrown on his journey.",objectivesText="Travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I do hope you don't suffer from allergies.",starts={{x=0.507,y=0.58,mapID=2112,npcID=196499}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Superbloom"},
[78447] = {id=78447,name="Aiding the Accord: Emerald Bounty",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="The Emerald Dream suffers at the forces of the Incarnate Fyrakk. In its turmoil, some of its seeds have trouble taking root. In exploring the Dream, I am certain you shall collect some special seeds. Plant them in soil and nourish them into a bloom, and I hear they will share bountiful gifts with you. Go forth and help life blossom in the Emerald Dream!",objectivesText="Travel to the Emerald Dream and plant 3 Dreamseeds of any quality in Emerald Bounty soil. Dreamseeds can be acquired from most activities in the Dream. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles. Progress: I wonder what gifts a flower can bestow?",starts={{x=0.507,y=0.58,mapID=2112,npcID=196499}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Aiding the Accord: Emerald Bounty"},
