[78643] = {id=78643,name="Fair Skies and Strong Winds",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=15105,mapID=2112,description="It has been a long road for us all, $p. But after persevering through hardship and strife, dragonkind stands poised to enter a new age. Before you leave for your next adventure, my fellow Aspects and I wish to thank you for all you have done for us.",objectivesText="Speak with Alexstrasza at the Seat of the Aspects in Valdrakken . Progress: The Dragon Isles stand in your debt.",starts={{mapID=2112,npcID=187678,x=0.583778,y=0.357111},{mapID=2239,npcID=216309,x=0.51,y=0.615}},ends={{mapID=2112,npcID=187678,x=0.583778,y=0.357111}},coords={mapID=2112,source="quest_giver",x=0.583778,y=0.357111},questType="world",worldTaskTitle="Fair Skies and Strong Winds"},
