[78821] = {id=78821,name="Blooming Dreamseeds",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=14529,mapID=2200,description="The Emerald Dream is about the harmony and balance of nature. For Amirdrassil to bloom, we need a rich variety of plants growing alongside the world tree. Plant seeds wherever you find fertile soil.",objectivesText="Plant dreamseeds in the Emerald Dream . Progress: How's the planting going?",starts={{mapID=2200,npcID=212797,x=0.498,y=0.62}},ends={{mapID=2200,npcID=212797,x=0.498,y=0.62}},coords={mapID=2200,source="quest_giver",x=0.498,y=0.62},questType="world",worldTaskTitle="Blooming Dreamseeds"},
[78931] = {id=78931,name="Technoscrying: The Mysteries of Dragonskull Island",expansion=9,mapID=2151,questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=213279,text="Item 1 Recovered"},{orderIndex=1,type=0,amount=1,objectID=213293,text="Item 2 Recovered"},{orderIndex=3,type=0,amount=1,objectID=213281,text="Ancient Shovel Recovered"},{orderIndex=4,type=0,amount=1,objectID=213713,text="Corked Vial Recovered"},{orderIndex=5,type=0,amount=1,objectID=213714,text="Blacksmith Hammer Recovered"},{orderIndex=6,type=15,amount=1,objectID=0,text="Recover the Items"},{orderIndex=7,type=0,amount=4,objectID=213279,text="Item 1 Recovered"},{orderIndex=8,type=0,amount=4,objectID=213293,text="Item 2 Recovered"},{orderIndex=9,type=0,amount=3,objectID=213281,text="Notable Item 1 Recovered"},{orderIndex=10,type=0,amount=3,objectID=213713,text="Notable Item 2 Recovered"},{orderIndex=11,type=0,amount=3,objectID=213714,text="Notable Item 3 Recovered"},{orderIndex=2,type=0,amount=1,objectID=214515,text="Notable Item (Any) Recovered"}},worldTaskTitle="Technoscrying: The Mysteries of Dragonskull Island",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[79321] = {id=79321,name="The Catalyst's Gift",level=70,requiredLevel=70,faction="both",expansion=9,zoneID=13862,mapID=2112,description="I have an urgent message for you, adventurer. The Revival Catalyst seems to be responding to the land's rumblings--perhaps even your feats! Miraculously, it now shares its power for nothing in return except one's mere presence. Antuka will know more. Go with haste, $p. This is wondrous news.",objectivesText="Speak to Antuka in Tyrhold.",starts={{mapID=2022,npcID=199336,x=0.765,y=0.342},{mapID=2112,npcID=213930,x=0.48,y=0.586}},ends={{mapID=2025,npcID=198695,x=0.606,y=0.538}},coords={mapID=2022,source="quest_giver",x=0.765,y=0.342},questType="world",worldTaskTitle="The Catalyst's Gift"},
[80385] = {id=80385,name="Last Hurrah: Dragon Isles",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2025,description="You've become quite popular with our allies, <name>! To the south the Iskaara Tuskarr need your help with their community feast. To the west the Maruuks have requested your aid with their hunts. To the north the Obsidian Outcasts request your help reclaiming Dragonbane Keep. Sounds like you have a full day ahead of you! Best of luck.",objectivesText="Assist the Tuskarr with their community feast, the Maruuk with their Hunt, and help reclaim Dragonbane Keep. Progress: We're lucky to have you on our side, <name>.",starts={{x=0.507,y=0.58,mapID=2112,npcID=196499}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Last Hurrah: Dragon Isles"},
[80386] = {id=80386,name="Last Hurrah: Zaralek Caverns and Time Rifts",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2025,description="Our allies are once again requesting your aid, <name>. In the Zaralek caverns the Dragonscale Expedition needs you to protect their researchers. We're also concerned with the Zaqali invasions in the Ohn'ahran Plains and Azure Span. Meanwhile, the Bronze Dragonflight has asked for you to help them deal with temporal anomalies to the east of Valdrakken . Hurry <name>, time is of the essence.",objectivesText="Protect the Researchers under Fire, loot a Secured Shipment from a Suffusion Camp, and assist Soridormi in dispelling a Time Rift. Progress: Do you bring news of your success?",starts={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Last Hurrah: Zaralek Caverns and Time Rifts"},
[80388] = {id=80388,name="Last Hurrah: Emerald Dream",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2025,description="The druids call for aid! Energy from the Emerald Dream is spreading across the Dragon Isles, please help them investigate it. They also ask you travel to the Emerald Dream and assist Sprucecrown in creating a Superbloom. Some of the druids also wish for you to plant Dreamseeds in the Emerald Dream. Please help them, <name>.",objectivesText="Gather one hundred Dreamsurge Coalescence across the Dragon isles, assist Sprucecrown in creating a Superbloom, and plant 3 Dreamseeds of any quality in the Emerald Dream. Dreamseeds can be acquired from most activities in the Emerald Dream. Progress: How are the druids doing?",starts={{x=0.507,y=0.58,mapID=2112,npcID=196499}},ends={{mapID=2112,npcID=196499,x=0.503,y=0.5605}},coords={mapID=2112,source="quest_giver",x=0.503,y=0.5605},questType="world",worldTaskTitle="Last Hurrah: Emerald Dream"},
[81993] = {id=81993,name="The Stormrider's Bond",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="This beauty is no ordinary gryphon. It's got the storm within it. I've been trying all day tae calm it down. It reminds me of an ol' Wildhammer myth. Stormrooks, they were called. Only able to be bonded by gryphon riders of great renown. If we can show ye got the spirit of the storm, maybe it'll open up tae ye. Try proving yerself in battle.",objectivesText="Collect 50 Storm Spirits by slaying powerful creatures of the Dragon Isles. Progress: I've never met such a stubborn gryphon before!",starts={{npcID=222277,x=0.382,y=0.946,zoneID=13862}},ends={{npcID=222277,x=0.382,y=0.946,zoneID=13862}},coords={x=0.382,y=0.946,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="The Stormrider's Bond"},
[81994] = {id=81994,name="A Sacred Connection",level=10,requiredLevel=10,faction="both",expansion=9,zoneID=13862,mapID=2112,description="Aye, the stormrook is beginning to take a liking to us. But the bond between rider and gryphon is forged over many trials. Ye may have the spirit of the storm, but let's show how ye mastered it. Time to really prove yer mettle in battle.",objectivesText="Collect 500 Storm Spirits by slaying powerful creatures of the Dragon Isles. Progress: I think I'm starting tae get this one to trust me.",starts={{npcID=222277,x=0.382,y=0.946,zoneID=13862}},ends={{npcID=222277,x=0.382,y=0.946,zoneID=13862}},coords={x=0.382,y=0.946,source="quest_giver",zoneID=13862},questType="world",worldTaskTitle="A Sacred Connection"},
}
end)
